import{_ as l,o as e,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2019-10-14 :: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2019-10-14 :: Ceph Orchestration Meeting","date":"2019-10-14T00:00:00.000Z","updated":"2019-10-21T00:00:00.000Z","tags":["Ceph","分布式存储","自动化测试","SSH 协排","Orchestration"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-10-14_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2019/2019-10-14_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780460162000}'),o={name:"posts/2019/2019-10-14_-_-_Ceph_Orchestration_Meeting.md"};function a(s,i,n,p,_,g){return e(),t("div",null,[...i[0]||(i[0]=[r('<h2 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h2><p>会议纪要</p><p><strong>会议时间</strong>： 2019年10月14日</p><p><strong>参会人员</strong>： Travis, Alfredo, Sage, Vickie, Anson Bullard, Federico 等</p><p><strong>会议内容</strong>：</p><p><strong>一、会议议程</strong></p><ol><li>Brooksie CI 和测试</li><li>Jenkins 更新</li><li>测试自动化</li><li>SSH 协程</li><li>其他议题</li></ol><p><strong>二、会议讨论</strong></p><ol><li><p><strong>Brooksie CI 和测试</strong></p><ul><li>讨论了如何简化测试流程，并引入其他测试框架。</li><li>Travis 正在改进测试流程，预计将在本周五提交相关PR。</li><li>Jenkins已更新，AWS thinkin&#39;s插件稳定，目前没有发现任何问题。</li></ul></li><li><p><strong>测试自动化</strong></p><ul><li>讨论了将测试自动化作为默认设置，以便在每次PR提交时自动运行测试。</li><li>Travis的PR将帮助实现这一目标，但需要升级Polly以确保其正常工作。</li><li>讨论了默认使用被动测试集的可行性，并避免运行不同测试套件可能带来的潜在问题。</li></ul></li><li><p><strong>SSH 协程</strong></p><ul><li>讨论了SSH协程的进展，目前Sage负责相关工作。</li><li>讨论了从Ansible协程过渡到SSH协程的可行性，以及如何进行过渡。</li><li>Federico将跟进相关讨论，并与团队成员沟通。</li></ul></li></ol><p><strong>三、行动计划</strong></p><ol><li>Travis 继续改进测试，并在本周五提交相关PR。</li><li>Sage 继续推进SSH协程相关工作。</li><li>Federico 跟进 SSH 协程的讨论，并与团队成员沟通。</li><li>讨论后续的测试自动化方案。</li></ol><p><strong>四、其他事项</strong></p><ul><li>无</li></ul><p><strong>五、会议总结</strong></p><p>本次会议主要讨论了测试自动化、SSH协程等议题，并制定了相应的行动计划。会议进展顺利，取得了一定的成果。</p><h2 id="识别的错误、误解或遗漏的重要信息" tabindex="-1">识别的错误、误解或遗漏的重要信息 <a class="header-anchor" href="#识别的错误、误解或遗漏的重要信息" aria-label="Permalink to &quot;识别的错误、误解或遗漏的重要信息&quot;">​</a></h2><ul><li>原始总结中未提及关于SSH协程的具体讨论内容，而原始字幕中有所提及。</li><li>原始总结中未提及Ansible协程的讨论，而原始字幕中有所提及。</li></ul><h2 id="相关标签" tabindex="-1">相关标签 <a class="header-anchor" href="#相关标签" aria-label="Permalink to &quot;相关标签&quot;">​</a></h2><ul><li>Ceph</li><li>分布式存储</li><li>自动化测试</li><li>SSH 协排</li><li>Orchestration</li></ul>',19)])])}const d=l(o,[["render",a]]);export{c as __pageData,d as default};
